}

// nonNegativeIntField reads an optional non-negative int field; a missing
// field is treated as zero.
func nonNegativeIntField(fields map[string]json.RawMessage, key string) (int, error) {
	raw, ok := fields[key]
	if !ok {
		return 0, nil
