			return nil, fmt.Errorf("Index %d is occupied by multiple transactions (%q and %q)",
				swap.Index, owner, swap.TxHash)
		}
		indexOwner[swap.Index] = swap.TxHash
		deduped = append(deduped, swap)
	}

	return deduped, nil
}

