	}
	ka := sortedSwapKeys(a)
	kb := sortedSwapKeys(b)
	for i := range ka {
		if ka[i] != kb[i] {
			return false
		}
	}
	return true
}

func sortedSwapKeys(swaps []Swap) []string {
	keys := make([]string, len(swaps))
	for i, swap := range swaps {
		keys[i] = strconv.FormatInt(swap.TxHash[0], 36) + "|" + swapKey(swap)
	}
	sort.Strings(keys)
	return keys
}

func swapKey(swap Swap) string {
