func makeSwap(tx, pool, trader string, in, out, gas int64, index int) Swap {
	return Swap{TxHash: tx, Pool: pool, Trader: trader, In: in, Out: out, GasPrice: gas, Index: index}
}

// ---------------------------------------------------------------------------
// DetectAll
